import { useLang } from '../i18n/LanguageContext';
import useInView from '../hooks/useInView';

const projectUrls = [
  'https://pasearporpasear.somee.com/',
  'https://novafadestudio.somee.com/',
  'https://gastontecheradev.github.io/e-commerce/',
];

const projectImgs = [
  'https://gastontecheradev.somee.com/images/proyecto-1.jpg',
  'https://gastontecheradev.somee.com/images/proyecto-2.jpg',
  'https://gastontecheradev.somee.com/images/proyecto-3.jpg',
];

export default function Projects() {
  const { t } = useLang();
  const [ref, visible] = useInView();

  return (
    <section className="section section-light" id="projects">
      <div className="container">
        <div className="section-header">
          <span className="section-number">{t.projects.number}</span>
          <h2 className="section-title">{t.projects.title}</h2>
        </div>

        <div className="projects-grid" ref={ref}>
          {t.projects.items.map((p, i) => (
            <a
              key={i}
              href={projectUrls[i]}
              target="_blank"
              rel="noopener noreferrer"
              className={`project-card fade-up fade-up-d${i + 1} ${visible ? 'visible' : ''}`}
            >
              <div className="project-img-wrap">
                <img src={projectImgs[i]} alt={p.title} className="project-img" loading="lazy" />
              </div>
              <div className="project-body">
                <h3 className="project-title">{p.title}</h3>
                <p className="project-desc">{p.desc}</p>
                <p className="project-tech">{p.tech}</p>
                <span className="project-link-label">
                  {p.linkLabel}
                  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                    <path d="M7 17 17 7" /><path d="M7 7h10v10" />
                  </svg>
                </span>
              </div>
            </a>
          ))}
        </div>
      </div>
    </section>
  );
}
